// The game's RAM by name: wram.timer() is the byte at wTimer, hram.demo_power_up()
// the one at hDemoPowerUp, read and written through the memory map like
// Memory's. The names come from the disassembly's labels (ram_fields.h,
// generated by tools/gen.c: wFooBar -> foo_bar). A label for more than a
// byte gives its first; .word() reads a dw there, and Memory reaches the
// bytes after it.
#pragma once

#include "native.hpp"

namespace wl3 {

class Wram {
public:
	explicit Wram(GB *gb) : gb_(gb) {}

#define WRAM(name, label) Byte name() const { return Byte(gb_, label); }
#define HRAM(name, label)
#include "ram_fields.h"
#undef WRAM
#undef HRAM

private:
	GB *gb_;
};

class Hram {
public:
	explicit Hram(GB *gb) : gb_(gb) {}

#define WRAM(name, label)
#define HRAM(name, label) Byte name() const { return Byte(gb_, label); }
#include "ram_fields.h"
#undef WRAM
#undef HRAM

private:
	GB *gb_;
};

} // namespace wl3
